    "guide": "교황, 주교, 미사처럼 낯선 낱말이 많이 나와요. 그럴 때는 \"가톨릭교회는 믿음을 사도들에게서 이어받았다고 설명하고, 그 하나 됨을 눈에 보이게 지키려 한다\"는 한 줄만 붙잡아 주세요. 교황의 권한이나 마리아, 성찬을 어떻게 이해하는지처럼 우리 교회와 다른 점이 나오면, 가톨릭교회가 자기 문서에서 이렇게 설명한다는 데까지만 읽고 그 너머는 교역자와 나누자고 안내해 주세요. 가톨릭 신자의 성찬 참여가 어떻게 이루어지는지 같은 궁금증도 마찬가지예요. 모르는 것이 나오면 모른다고 해도 되고, 역사 자료와 문서가 다 말하지 않는 것은 모른다고 말해도 돼요. \"우리와 같은 것, 다른 것, 이 교회에서 배울 점\" 문단에서 우리 교회의 입장을 더하는 일은 교역자 몫이에요.",
