            "h": "물려받은 믿음을 지키려는 집",
            "t": "1962년 10월 11일, 바티칸의 베드로 대성당에서 교황 요한 23세가 연설했습니다. 제2차 바티칸 공의회(교회의 주교들이 함께 모여 중요한 일을 의논하는 큰 모임)가 문을 여는 날이었습니다. 교황은 로마 교회의 주교이고, 주교는 한 지역의 교회를 맡아 돌보는 사람입니다.\n\n연설에서 교황은 이 모임이 가장 마음 쓰는 일이 그리스도교 가르침이라는 거룩한 맡김, 곧 물려받은 믿음을 잘 지키고 더 힘 있게 가르치는 것이라고 말했습니다. 또 믿음의 내용과 그것을 전하는 말투는 다르다고 구분했고, 엄하게 다그치기보다 자비로 치료하는 길을 고르겠다고 했습니다.¹\n\n그런데 이 맡김은 누구에게서 왔을까요? 가톨릭교회는 사도들에게서 왔다고 설명합니다. 예수님이 열두 사도를 한 모임으로 세우시고 그 머리에 베드로를 두셨고, 사도들은 자기 일을 이어받을 사람을 세웠으며, 그 일을 이어받은 이들이 주교라고 가르칩니다. 이 짜임은 하나님 나라가 완성될 때까지 이어진다고 봅니다.²\n\n그러면 교황은 왜 있을까요? 『가톨릭교회 교리서』는 눈에 보이는 끈으로 같은 믿음, 함께 드리는 예배, 사도 때부터 이어진 직분을 꼽습니다. 교회 헌장(공의회 문서, 1964)은 베드로의 자리를 이은 로마의 주교를 교회의 하나 됨의 오래가는 눈에 보이는 뿌리라고 부릅니다. 두 말을 이으면 가톨릭교회가 하나 됨을 마음속에만 두지 않고 눈에 보이게 지키려 한다는 뜻이 됩니다. 요한 23세는 바로 그 자리에서 이 모임을 열었습니다.³",
