            "t": "이 장면에서 먼저 나오는 것은 직분이 아니라 질문입니다. 사람들이 말하는 예수님과 제자가 고백하는 예수님은 같지 않습니다. 베드로의 대답이 나온 다음에야 예수님은 교회를 말씀하십니다. 교회는 이 고백 위에서 시작합니다.\n\n가톨릭교회는 이 장면을 베드로가 열두 사람 가운데 첫째 자리를 받은 때로 읽습니다. 교리서는 베드로의 일이 이 믿음을 지키고 형제들을 굳게 하는 것이라 합니다. 또 열쇠는 교회를 다스리는 권한이며 가르치고 용서하고 규율을 정하는 일을 포함한다고 설명합니다.⁷\n\n우리와 같은 것. 니케아-콘스탄티노플 신경은 예수님을 하나님의 아들이신 주님으로 고백하고, 하나이고 거룩하고 보편되며 사도로부터 이어 온 교회를 고백합니다. 가톨릭교회는 교리서 811항에서 이 말을 자기 이해의 바탕으로 둡니다.\n\n다른 것. 이 바위와 열쇠를 어떻게 읽는지, 교회를 누가 어떻게 이끄는지는 교회마다 다릅니다. 일치 교령 3항은 교회의 구조를 가톨릭교회와 다른 교회가 갈라지는 점 가운데 하나로 꼽습니다. 정교회는 1672년 신앙고백 10조에서 교회의 머리가 그리스도 자신이며 주교들이 각 지역 교회를 이끈다고 고백합니다. 동쪽 교회와는 1054년 무렵 교제가 끊어졌고, 1965년 두 교회가 서로의 파문을 기억에서 거둔 이야기는 2과에서 읽습니다. 개신교 교회들이 교회를 누가 어떻게 이끄는지는 12과의 비교표에서 만납니다.⁸\n\n이 교회에서 배울 점. 가톨릭교회는 교회의 하나 됨을 눈에 보이게 가꾸려 하고, 말씀의 식탁과 성찬의 식탁을 하나의 예배로 이어 드립니다. 흩어진 곳의 교회가 한 몸으로 이어져 있다는 감각은 우리가 함께 받은 선물로 배울 만합니다.",
