    "guide": "이콘, 성인, 성사, 성령이 나오심에 관한 신경의 차이처럼 우리 교회와 다른 점이 나올 수 있어요. 그럴 때는 \"정교회는 자기 예배와 신앙고백에서 이렇게 말한다\"는 데까지만 읽고, 그 너머는 교역자와 나누자고 안내해 주세요. 낯선 이름이 많다면 \"정교회는 믿음을 예배 안에서 노래로 고백해 온 교회\"라는 한 줄만 붙잡아도 충분해요. 1054년과 1965년 이야기는 두 교회 모두의 아픔과 화해의 노력으로 같은 무게로 읽어 주세요. 모르는 것이 나오면 모른다고 해도 되고, 자료가 다 말하지 않는 것은 모른다고 말해도 돼요. \"우리와 같은 것, 다른 것, 이 교회에서 배울 점\" 문단에서 우리 교회의 입장을 더하는 일은 교역자 몫이에요.",
