            "kind": "read",
            "h": "하늘에 있는 듯했다는 열 사람",
            "t": "옛 러시아 연대기가 987년 항목에 전하는 이야기입니다. 블라디미르 대공은 여러 믿음을 전하러 온 사람들의 말을 들었습니다. 신하들은 말만 듣지 말고 믿을 만한 사람을 보내 직접 보게 하라고 권했고, 대공은 열 사람을 뽑아 길을 떠나게 했습니다. 이들은 여러 나라의 예배를 보았고, 그리스 사람들이 하나님께 예배하는 곳에도 갔습니다.¹\n\n돌아온 열 사람은 대공 앞에서 본 것을 보고했습니다. 그리스 사람들의 예배당에서는 하늘에 있는지 땅에 있는지 알 수 없었다고 말했습니다. 땅 위에는 그만한 화려함과 아름다움이 없다고도 했습니다.¹\n\n열 사람이 본 것은 글이나 가르침이 아니라 예배였습니다. 그렇다면 정교회 사람들은 그 예배가 무엇 위에 서 있다고 말할까요? 1672년 예루살렘에 모인 정교회 주교들의 신앙고백이 한 대답을 남겼습니다. 정교회가 자기를 말하는 여러 글 가운데 하나입니다. 이 고백은 성경이 하나님이 주신 말씀이지만 교회가 읽어 온 대로 읽어야 한다고 말합니다(2조). 같은 성령이 성경과 교회를 함께 이끄시므로 교회의 증언도 가볍지 않다는 까닭을 덧붙입니다.²\n\n그래서 정교회는 자기 예배와 믿음을 새로 만든 것이 아니라 성령이 교회를 통해 가르쳐 온 것으로 말합니다. 12조는 성령이 교회의 스승들과 공의회를 통해 교회를 가르치신다고 고백합니다.³ 그 믿음은 예배 안에서 고백됩니다. 예배에서 신경(믿음의 내용을 고백하는 짧은 글)을 부르기 전에 사제는 서로 사랑하여 한마음으로 고백하자고 권합니다.⁴",
