          {
            "id": "cd02-r2",
            "kind": "read",
            "h": "신성한 예배의 한 아침",
            "t": "정교회가 일요일에 드리는 신성한 예배(성찬을 중심으로 한 예배의 이름)를 따라가 봅니다. 여기서는 요한 크리소스토모스의 이름이 붙은 예배의 공개 본문을 따릅니다.⁴\n\n예배는 삼위일체 하나님의 나라를 찬양하는 사제의 말로 열립니다. 이어 평화를 구하는 기도가 이어지고 사람들이 응답합니다. 세 번 거룩하다고 부르는 찬송을 모두가 함께 부른 뒤 사도들의 편지와 복음서를 읽습니다. 복음을 읽기 전에 지혜를 외치는 소리와 함께 서서 거룩한 복음을 듣자는 권면이 있고, 사람들은 읽기 앞뒤로 주님께 영광을 돌리는 말을 노래하거나 말합니다.⁴\n\n다음은 케루빔(성경에 나오는 하늘의 존재) 찬송입니다. 사람들은 자기들이 케루빔을 신비롭게 나타내며 삼위일체께 거룩하다고 노래한다는 뜻의 노래를 부르고, 세상의 걱정을 내려놓자고 합니다. 이어 예물을 들고 들어오는 행렬이 지나가고, 문을 지키라는 외침 뒤에 모두가 함께 신경을 부릅니다.⁴\n\n감사 기도에 앞서 바르게 서서 경외하는 마음으로 평화 가운데 거룩한 예물을 드리자는 권면이 있습니다. 감사 기도에서 사람들은 거룩하다는 찬양을 노래하고, 사제는 성령이 이 예물 위에 내려오시기를 청합니다.⁴\n\n모두가 주님의 기도를 드린 뒤 거룩한 것은 거룩한 이들을 위한 것이라는 선언이 울리고, 하나님을 경외하며 믿음과 사랑으로 나오라는 초대가 이어집니다. 성찬을 받은 뒤 사람들은 참 빛을 보았고 하늘의 성령을 받았다고 노래합니다. 마지막에 평안히 나아가자는 말에 사람들은 주님의 이름으로라고 답합니다.⁴"
          },
          {
            "id": "cd02-r3",
            "kind": "read",
            "h": "정교회가 자기를 말하는 글",
            "t": "이 카드는 정교회가 예배와 신앙고백으로 자기를 설명하는 글을 따라 읽습니다. 정교회는 믿음을 먼저 예배 안에서 고백합니다. 예배에서 함께 부르는 신경은 4세기 두 공의회가 가다듬은 글이고, 서쪽 교회들과 개신교도 함께 받는 글입니다. 이 신경은 아들을 빛에서 비롯된 빛이라 부르고 성령을 생명을 주시는 주님이라 부릅니다. 성령이 아버지에게서 나오신다고 고백하고, 하나이고 거룩하고 보편되고 사도로부터 이어 온 교회를 믿는다고 밝힙니다. 죄를 용서하는 한 번의 세례를 고백하고, 죽은 이의 부활과 다가올 세상의 생명을 기다린다고 말합니다.⁵\n\n1672년 예루살렘 회의의 신앙고백은 열여덟 조로 되어 있습니다. 첫 조는 한 분 하나님이 아버지와 아들과 성령이심을 고백하며 시작합니다. 열여덟 조는 삼위일체와 성경, 교회와 성사 같은 믿음의 항목을 차례로 고백합니다. 8조는 그리스도만이 유일한 중보자라고 하면서도 신자들이 마리아와 천사와 성인들에게 자기를 위해 기도해 달라고 청한다고 밝힙니다. 이콘(예수님과 성인들을 그린 거룩한 그림)에 드리는 존경은 그려진 분께 이르고 경배는 하나님께만 드린다고 설명합니다.⁶\n\n정교회와 나란히 오리엔탈 정교회라는 오래된 교회 가족도 있습니다. 두 가족은 그리스도를 서로 다른 낱말로 말하며 오랫동안 따로 지냈습니다. 그러나 1989년과 1990년에 낸 합의 성명은 두 가족이 같은 믿음을 지켜 왔다고 밝혔고, 처음 세 공의회를 함께 받는 공통 유산으로 꼽습니다. 이 성명은 두 가족이 오랜 대화 끝에 낸 글입니다.⁷\n\n아래 표는 예루살렘 신앙고백이 몇 가지 질문에 답한 곳을 모은 참고입니다.⁶\n\n| 질문 | 조 | 한 줄 답 |\n| --- | --- | --- |\n| 성사(그리스도께서 교회에 주셨다고 믿는 거룩한 예식)는 몇 가지인가요? | 15조 | 일곱 가지이며 그보다 많거나 적게 두지 않습니다 |\n| 성찬의 빵과 포도주는 무엇인가요? | 17조 | 주님의 몸과 피로 바뀌어 참으로 계신다고 고백하고 그분께 경배합니다 |\n| 교회의 머리는 누구인가요? | 10조 | 그리스도 자신이고, 주교들이 각 지역 교회를 이끕니다 |"
          }
