            "t": "요한복음은 예수님의 이야기를 모든 것의 시작보다 앞선 곳에서 엽니다. 이 첫머리는 창세기가 하늘과 땅의 시작을 말하던 첫머리를 떠올리게 합니다. 시작에 이미 '말씀'이 계셨고, 말씀은 하나님 곁에 있었으며 그분 자신이 하나님이셨다고 합니다. 지어진 모든 것이 이 말씀을 통해 생겼고, 말씀과 상관없이 생긴 것은 하나도 없다고 합니다.\n\n그분 안에 생명이 있었고, 그 생명은 사람들에게 길을 밝혀 주는 빛이었습니다. 어둠 속에서 빛이 비추고 있는데, 어둠은 그 빛을 당해 내지 못했습니다. 빛은 창세기에서 맨 먼저 나타난 것이기도 하고, 요한복음 8장과 9장에서 예수님이 자신을 가리켜 쓰시는 말이기도 합니다.\n\n요한복음 1장은 뒤에서 이 말씀이 사람이 되어 우리 가운데 사셨다고 이어 말합니다. 오늘 본문 1~5절은 그보다 먼저, 말씀의 시작과 그 빛을 보여 줍니다. 이 다섯 절에는 아직 예수님의 이름이 나오지 않고, 이름은 17절에서야 나옵니다.",
