            "t": "이 책은 요한복음 1장의 빛을 정교회 예배의 노래와 이어 읽어 봅니다. 신경은 아들을 빛에서 비롯된 빛이라 말하고, 성찬을 받은 뒤 사람들은 참 빛을 보았다고 노래합니다.⁵ 말씀 안의 생명이 사람들에게 길을 밝히는 빛이라는 요한복음의 말이 예배의 노래로 불리는 것입니다.\n\n서쪽 교회와 정교회의 교제는 1054년 무렵 끊어졌다고 흔히 말합니다. 1965년 12월 7일, 로마와 이스탄불에서 같은 날 같은 글이 낭독되었습니다. 교황 바오로 6세와 총대주교 아테나고라스가 함께 낸 글입니다. 두 교회는 그때 오간 상처 준 말과 행동을 아쉬워하고, 1054년의 파문(교회에서 내보낸다는 선언)을 기억에서 거두었습니다. 그러면서도 오랜 차이를 풀려면 아직 갈 길이 있다고 밝혔습니다.⁸\n\n우리와 같은 것. 니케아-콘스탄티노플 신경은 하나님을 삼위로 고백하고, 아들을 하나님의 아들로, 성령을 생명을 주시는 주님으로 고백합니다. 정교회와 우리가 함께 받는 글입니다.\n\n다른 것. 신경에서 성령이 어디서 나오시는지를 서쪽 교회의 신경은 아버지와 아들에게서, 정교회의 예배 신경은 아버지에게서라고 적습니다. 가톨릭 교리서 247항도 이를 정교회와 의견이 갈리는 점으로 적습니다. 성인과 이콘, 성찬과 성사를 어떻게 말하는지도 교회마다 다르며, 12과의 비교표에서 같은 질문에 교회마다 자기 문서가 답한 대로 만납니다.⁸\n\n이 교회에서 배울 점. 정교회의 예배 노래에서 사람들은 자기들이 케루빔을 신비롭게 나타내며 삼위일체께 거룩을 노래한다고 말합니다. 예배를 한 시간의 모임에 그치지 않고 하늘의 찬양에 함께하는 일로 보는 눈, 아름다운 노래로 믿음을 고백해 온 모습은 우리도 선물로 받을 만합니다.",
