          {
            "id": "cd03-r2",
            "kind": "read",
            "h": "종이 울리면: 아침 기도 한 장면",
            "t": "이 카드는 1662년판 기도서의 아침 기도 차례를 따라갑니다. 종소리를 듣고 모인 사람들 손에는 기도서가 있습니다. 언제 서고 언제 무릎을 꿇을지, 누가 말하고 누가 따라 말할지가 책에 적혀 있습니다.\n\n먼저 사제가 큰 소리로 성경 구절을 한두 개 읽고, 하나님 앞에서 죄를 고백하자고 초대합니다. 모두 무릎을 꿇고 사제를 따라 함께 고백합니다. 고백은 길 잃은 양처럼 제 마음 가는 대로 걸었다는 말로 시작합니다. 그다음 사제 혼자 서서 용서를 선포하고, 모두가 주기도문을 드립니다.\n\n이어 사제와 사람들이 \"주여, 내 입술을 열어 주소서\" 하는 짧은 말을 주고받고, 모두 일어서서 찬양하며 시편을 차례로 읽거나 부릅니다. 읽는 사람은 서서 구약을 읽되, 모인 사람 모두가 가장 잘 들을 수 있게 몸을 돌립니다. 영어로 테 데움이라는 찬양을 한 뒤에는 신약을 읽고 다시 찬양합니다.\n\n그다음 모두 서서 사도신경으로 믿음을 고백하고, 무릎을 꿇고 짧은 기도를 드립니다. 그날의 기도, 평화를 구하는 기도, 은혜를 구하는 기도가 이어집니다. 앞의 것은 그날의 성찬 예배와 같은 기도이고, 뒤의 둘은 날마다 같습니다. 나라와 교회를 위한 기도를 드린 뒤 고린도후서에서 가져온 은혜의 말로 마칩니다.\n\n이 순서는 날마다 되풀이됩니다. 읽기의 질서가 구약의 대부분을 한 해에, 신약을 한 해에 두 번 읽도록 짜여 있어서 같은 순서의 아침 속에서 성경이 차례로 읽힙니다. 모인 사람들은 이렇게 하루를 엽니다.⁵"
          },
          {
            "id": "cd03-r3",
            "kind": "read",
            "h": "성공회가 자기를 말하는 글",
            "t": "이 카드는 성공회가 스스로를 설명하는 두 글, 16세기의 39개조와 1888년 램버스 회의의 결의 11을 따라 읽습니다.⁶\n\n성공회는 성경을 으뜸에 둡니다. 39개조 6조는 먼저 구약과 신약의 책을 하나하나 적어 성경이 무엇인지 밝힙니다. 성공회는 구원에 필요한 모든 것이 성경에 담겨 있다고 보아, 성경에 없거나 성경으로 밝힐 수 없는 것은 믿음의 조항으로 요구하지 않습니다. 예식은 다르게 다룹니다. 전통과 예식은 어디서나 똑같을 필요가 없고 나라와 때와 풍습에 따라 달라질 수 있습니다. 나라의 교회가 사람이 만든 예식을 고칠 수도 있습니다. 다만 모든 일은 사람을 세우는 데 쓰여야 하고 하나님의 말씀에 어긋나서는 안 됩니다(34조). 한 나라 안에서는 예식을 한 가지로 맞추되(기도서 서문), 나라마다 달라질 여지도 열려 있는 셈입니다.\n\n다른 교회들과 하나 되는 길을 찾을 때에는 함께 붙들 것이 무엇인지 물어야 했습니다. 결의 11은 이 네 가지를 하나 되는 길에 다가갈 바탕이라고 부릅니다. 성경, 신경, 성례, 감독직(주교의 직분)입니다. 신경은 사도신경을 세례 때의 고백으로, 니케아 신경을 믿음을 충분히 말한 글로 받습니다. 성례는 세례와 주의 만찬이며, 그리스도의 말씀과 그분이 정하신 것으로 베풉니다.\n\n넷째인 감독직에는 \"각 나라와 백성의 필요에 맞게\"라는 말이 붙습니다. 나라마다 달라질 수 있는 것을 인정하는 34조와 같은 말투입니다. 아래 표는 본문에서 다루지 않은 질문에 39개조가 답한 모습입니다.\n\n| 질문 | 39개조의 대답 |\n| --- | --- |\n| 교회가 예식을 정할 권한은 | 20조: 있다. 다만 기록된 하나님의 말씀에 어긋나게 정할 수 없다 |\n| 함께 받는 신경은 | 8조: 니케아 신경과 사도신경을 받는다(1571판은 아타나시우스 신경도). 성경으로 밝힐 수 있기 때문이다 |\n| 그리스도께서 정하신 성례는 | 25조: 세례와 주의 만찬, 둘 |\n| 예배의 말은 | 24조: 공적인 기도와 성례를 사람들이 알아듣는 말로 한다 |"
          }
