            "t": "이 과는 에베소서 4장을 성공회가 기도서 한 권을 함께 쓰는 모습과 이어 읽어 봅니다. 바울이 말하는 하나 됨은 먼저 선물입니다. 성령께서 이미 마련하셨고, 성도는 서로를 사랑으로 받아 주며 그것을 지킵니다. 하나 됨이 모두가 똑같아진다는 뜻은 아닙니다. 7절은 각 사람에게 다른 은혜가 주어졌다고 하기 때문입니다. 39개조 34조도 예식이 어디서나 똑같을 필요는 없다고 하니, 하나로 붙드는 것과 달리 둘 수 있는 것을 함께 말하는 길입니다.\n\n우리와 같은 것. 니케아-콘스탄티노플 신경은 한 세례를 고백합니다. 웨스트민스터 신앙고백 25장 2절은 눈에 보이는 공교회가 한 민족에 매이지 않고 세계 곳곳의 신자로 이루어진다고 합니다. 같은 고백 21장 3절은 소리 내어 하는 기도를 듣는 이들이 아는 말로 하라고 합니다. 같은 고백 27장 4절과 39개조 25조는 그리스도께서 정하신 성례가 세례와 성찬 둘이라는 데서 만납니다.\n\n다른 것. 하나 됨을 지키는 질서의 모양입니다. 성공회는 기도서 한 권과 역사적 감독직을 말합니다(램버스 1888 결의 10과 11). 우리 교회는 주교를 두지 않고, 직분과 예배의 모양이 다릅니다. 이 차이는 5과에서 우리 교회의 글로 다시 만납니다.\n\n이 교회에서 배울 점. 먼 곳의 신자와 같은 순서로 성경을 읽고 같은 말로 날마다 기도하는 선물입니다. 하나 됨이 기도의 말과 성경 읽기의 질서 속에서 날마다 눈에 보이게 되는 모습을 볼 수 있습니다.⁷",
