            "t": "1. 1662년판 기도서 서문 「교회 예배에 관하여」(Concerning the Service of the Church): 사제는 집에 있고 달리 막히는 일이 없으면 아침 기도와 저녁 기도를 날마다 교회에서 드리고, 사람들이 올 수 있도록 종을 울린다(기도서 1662, 영국 교회 공개 본문).\n2. 같은 서문이 밝힌 까닭: 성경을 한 해에 거의 다 읽던 옛 질서가 복잡해져 읽을 곳을 찾는 데 읽는 시간보다 더 걸리곤 한 일, 성경을 차례로 읽는 질서를 세움, 온 나라가 한 가지 예식을 씀, 교회에서 읽고 부르는 것을 영어로 하여 모인 사람이 알아듣고 덕을 세움(기도서 1662).\n3. 1662년판 「서문」(The Preface): 교회가 \"두 극단 사이의 가운데\"를 지키려 했다는 말, 기도서를 쓰지 못하던 때와 왕정이 돌아온 뒤의 개정, 평화와 하나 됨과 경건이라는 목표, 두 관구의 성직자 회의가 검토해 승인한 일(기도서 1662).\n4. 램버스 1888 결의 10(기도서는 한 교구나 한 지역의 것이 아니라 모두의 것이므로 고치려면 다른 곳에 미칠 영향을 먼저 살필 것).\n5. 1662년판 아침 기도의 차례와 읽기의 질서(구약의 대부분은 한 해에 한 번, 신약은 한 해에 두 번)는 기도서 1662. 읽는 사람이 서서 모인 사람이 가장 잘 들을 수 있게 몸을 돌린다는 지시도 같은 책의 아침 기도.\n6. 39개조는 영국 교회 공개 본문의 머리말이 1562년 성직자 회의의 합의와 1571년 서명을 적는다. 이 시리즈의 3권 기준표는 1562~1563년으로 쓴다. 6조, 20조, 34조, 8조, 24조, 25조는 39개조. 결의 11(다른 교회와 하나 되는 길의 바탕으로 말한 네 가지)은 램버스 1888.\n7. 니케아-콘스탄티노플 신경의 한 세례는 CCEL 게시 본문. 웨스트민스터 신앙고백 21장 3절, 25장 2절, 27장 4절은 웨스트민스터 신앙고백(OPC 게시 본문). 성공회의 역사적 감독직과 기도서는 램버스 1888 결의 10과 11, 39개조 25조와 34조는 39개조."
