          {
            "id": "cd04-r2",
            "kind": "read",
            "h": "성찬 예배 한 장면: 말씀과 식탁",
            "t": "이 카드는 북미의 루터교회가 쓰는 『루터교 예배서』(1978)의 성찬 예배 순서를 따라갑니다. 한국의 루터교회 예배는 말과 모양이 다를 수 있습니다. 신앙고백 7조는 예식이 어디서나 같을 필요가 없다고 합니다.⁵ 그래서 교회마다 노래와 말이 조금씩 다를 수 있습니다.\n\n먼저 인도하는 목사가 하나님의 이름으로 예배를 열고, 모두 함께 죄를 고백하면 목사가 용서를 선포합니다. 모두 함께 노래한 뒤 키리에(\"주여, 불쌍히 여기소서\" 하고 간구하는 노래)와 찬양을 부릅니다. 목사가 인사를 건네고 그날의 기도를 드리면 모두 \"아멘\" 하고 응답합니다.\n\n말씀의 시간에는 구약과 시편, 신약을 읽고, 모두 일어서서 복음서를 듣습니다. 복음서 앞에서는 짧은 노래를 부르고, 읽은 뒤에는 목사가 \"주님의 복음입니다\" 하고 맺습니다. 목사의 설교는 앉아서 듣고, 서서 사도신경으로 믿음을 고백한 뒤 그날의 찬송을 부르고 함께 기도합니다.\n\n그다음 헌금을 드리고 식탁이 차려지는 동안 일어서서 헌금의 기도를 합니다. 목사가 감사의 기도를 이끌면 모두 거룩하다고 노래하고, 목사는 성찬을 세우신 말씀을 읽고 모두 주기도문을 드립니다. 사람들은 \"그리스도의 몸, 당신을 위해 주신 것\"이라는 말과 함께 받고 노래합니다. 나눈 뒤에는 목사가 축복하고, 감사의 노래와 기도로 마친 뒤 잠시 조용히 머뭅니다. 마지막에 찬송이 있고, 목사가 \"평안히 가서 주님을 섬기십시오\" 하면 모두 \"하나님께 감사합니다\" 하고 대답합니다.⁵"
          },
          {
            "id": "cd04-r3",
            "kind": "read",
            "h": "루터교가 자기를 말하는 글",
            "t": "이 카드는 루터교가 스스로를 설명하는 글, 소요리문답과 아우크스부르크 신앙고백을 따라 읽습니다.⁶\n\n루터는 여러 교회를 직접 돌며 살펴본 뒤, 그 딱한 형편을 소요리문답 서문에 적었습니다. 그리스도인이라 하면서도 주기도문과 신경과 십계명을 외우지 못하는 사람이 많았고, 특히 마을에 그런 사람이 많았습니다. 루터는 목사들에게도 맡은 직분에 힘써 가르치라고 권했습니다.\n\n그래서 1529년에 요리문답(질문과 답으로 믿음을 가르치는 책)을 썼습니다. 각 부분은 \"이것은 무엇인가\" 하고 묻고 짧게 답합니다. 십계명, 신경, 주기도문, 세례, 죄의 고백, 성찬을 차례로 다루고, 가정의 어른이 식구들에게 쉽게 가르치도록 짜 놓았습니다. 해마다 같은 모양으로 가르치라고 권했고, 부록에는 아침과 저녁에 드릴 기도도 있습니다.\n\n루터교는 믿음 자체를 선물로 이해합니다. 소요리문답은 내 이성이나 힘으로는 믿을 수 없고 성령이 복음으로 불러 믿음 안에 지켜 주신다고 풀고, 고백 5조는 성령이 말씀과 성례를 도구 삼아 믿음을 일으키신다고 가르칩니다. 믿음은 우리 손에서 나온 것이 아니라 주어진 것이라는 뜻입니다.⁷\n\n1999년 10월 31일, 1530년 고백이 나온 도시 아우크스부르크에서 루터교세계연맹과 가톨릭교회가 칭의에 관한 공동 선언을 확인했습니다. 선언 15항은 두 교회가 은혜만으로, 그리스도의 구원 사역을 믿는 믿음으로, 우리 공로 때문이 아니라 하나님께 받아들여진다고 함께 고백한다고 적습니다.⁸\n\n| 질문 | 루터교 글의 대답 |\n| --- | --- |\n| 세례는 무엇인가 | 소요리문답: 하나님의 명령과 말씀이 함께하는 물. 죄를 용서하고 죽음과 마귀에게서 구한다 |\n| 성찬은 무엇인가 | 아우크스부르크 10조와 소요리문답: 빵과 포도주 안에 그리스도의 몸과 피가 있다. 죄를 용서하고 생명과 구원을 준다 |\n| 선한 행위는 어디에 있나 | 아우크스부르크 6조와 20조: 믿음에서 선한 행위가 나오지만 그것으로 의롭다고 받아들여지는 것은 아니다 |"
          }
