            "t": "로마서 3장 앞부분에서 바울은 유대 사람이든 이방 사람이든 모두 죄 아래 있다고 말했습니다. 21절은 이제 율법과는 따로 하나님의 의로움이 드러났다고 하며, 율법과 예언자들도 그것을 증언한다고 합니다. 그래서 21절의 \"이제\"는 새 소식이 시작되는 자리입니다.\n\n22~24절은 이 의로움이 예수 그리스도를 믿는 믿음을 통해 믿는 모든 사람에게 온다고 합니다. 차별이 없는 까닭은 모두 죄를 지어 하나님의 영광에 모자라기 때문입니다. 그 모든 사람이 그리스도 예수 안의 속량(값을 치르고 풀어 주심)으로 대가 없이 의로운 사람으로 받아들여집니다.\n\n25절은 하나님이 그리스도를 속죄(죄를 용서받게 하는 길)의 자리에 세우셨다고 하며, 26절은 이렇게 하심으로 하나님도 의로우시고 예수를 믿는 사람도 의롭다고 하신다고 말합니다. 27~28절은 그러므로 자랑할 자리가 없다고 합니다. 사람이 의롭다고 인정받는 것은 율법의 행위와 상관없이 믿음으로이기 때문입니다.",
