            "t": "1. 루터의 1545년 라틴어 저작 전집 서문(Thornton 영역, GHDI 게시): 시편 강의, 로마서 1:17의 \"하나님의 의로움\"을 벌하는 공정함으로 읽었던 일, 앞뒤를 다시 읽고 선물로 받는 의로움으로 읽게 된 일, \"열린 문으로 낙원에 들어선 것 같았다\"는 돌아봄(루터 1545 서문).\n2. 아우크스부르크 신앙고백 머리말: 황제 카를 5세가 종교를 둘러싼 다툼과 방어 문제를 의논하려고 소집한 1530년 아우크스부르크 제국의회, 서명한 군주들과 도시들이 라틴어와 독일어로 신앙고백을 내놓음(아우크스부르크, Gutenberg 275 게시 영역).\n3. 아우크스부르크 신앙고백 4조(사람은 자기 힘이나 행위가 아니라 그리스도 때문에 믿음으로 값없이 의롭게 된다).\n4. 아우크스부르크 신앙고백 21조 끝의 \"교리의 요지\" 문단(성경에서도, 공교회에서도, 로마 교회가 알려진 글에서도 어긋나는 것이 없다)과 7조(교회, 예식이 어디서나 같을 필요가 없음).\n5. 예배 순서와 응답은 『루터교 예배서』(Lutheran Book of Worship, 1978)의 성찬 예배를 다시 실은 북미 루터교회(NALC) 2023년 예배 소책자의 순서. 아우크스부르크 신앙고백 7조(예식이 어디서나 같을 필요가 없음).\n6. 루터의 소요리문답(1529) 서문과 본문: 교회를 돌아본 일, 주기도문과 신경과 십계명을 외우지 못하는 사람들, 목사들에게 맡은 직분에 힘쓰라는 권면, 한 가지 모양으로 해마다 가르치라는 권면, 가장이 식구들에게 쉽게 가르친다는 머리말, 십계명 신경 주기도문 세례 죄의 고백 성찬의 순서, 아침과 저녁 기도 부록(소요리문답 루터; CPH 『Luther's Small and Large Catechisms』 1986년 번역 공개 PDF와 Project Gutenberg 게시 Smith 영역). 아우크스부르크 신앙고백은 아우크스부르크.\n7. 소요리문답 신경의 셋째 항(내 이성이나 힘으로는 믿을 수 없고 성령이 복음으로 부르신다)과 아우크스부르크 신앙고백 5조(말씀과 성례를 통해 성령이 주어지고 믿음이 일어난다).\n8. 공동 선언 1999 15항과 공동 공식 성명(1999년 10월 31일 아우크스부르크, 루터교세계연맹 게시 영문 원본).\n9. 웨스트민스터 신앙고백 11장 1절, 28장 4절, 29장 7절(웨스트민스터 신앙고백, OPC 게시 본문). 아우크스부르크 신앙고백 9조와 10조."
