            "h": "삶에서도 죽음에서도 하나뿐인 위로",
            "t": "1563년, 독일 하이델베르크가 있는 팔츠 지방을 다스리던 프리드리히 3세는 교회와 학교에서 쓸 가르침의 책을 펴내게 하고 직접 머리말을 썼습니다. 그 지방 교회들은 몇 해 앞서 다툼으로 나뉘어 있었고, 그는 가르침을 하나로 모으고 젊은 세대에게 단단한 바탕을 주고 싶어 했습니다.¹ 이 책이 하이델베르크 요리문답(믿음을 묻고 답하는 말로 가르치는 글)입니다.\n\n이 책은 칼뱅의 요리문답 같은 앞선 글들을 살피며 쓰였습니다. 이런 가르침을 따라 자란 교회들을 개혁교회라 부릅니다.¹ 첫 물음은 짧지만 깊습니다. 삶에서도 죽음에서도 오직 하나뿐인 위로가 무엇이냐고 묻습니다. 답은 내가 몸도 영혼도 신실하신 구주 예수 그리스도께 속해 있다는 것입니다. 그분이 나의 모든 죄값을 치르셨고, 아버지의 뜻 아래 나를 지켜 주신다고 이어집니다.²\n\n둘째 물음은 이 위로 안에서 살려면 알아야 할 것이 셋이라고 답합니다. 내 죄와 비참이 얼마나 큰지, 거기서 어떻게 건져졌는지, 그 은혜에 어떻게 감사하며 살지입니다.² 책은 한 해 쉰두 번의 주일에 한 부분씩 풀어 가르칠 수 있게 나뉘어서, 한 교회가 한 해 동안 같은 물음 앞에 함께 서게 됩니다.¹\n\n같은 믿음의 집은 영국 섬에서도 자랐습니다. 1647년 스코틀랜드 교회는 웨스트민스터 신앙고백(믿음을 조목조목 적어 고백한 글)을 받아들였고, 함께 만든 소요리문답은 첫 물음에서 사람의 으뜸 되는 목적이 하나님께 영광을 돌리고 그분을 영원히 기뻐하는 것이라고 답합니다.³ 개혁교회는 이렇게 하나님의 영광과, 그리스도께 속했다는 위로를 자기가 지키려는 것으로 말합니다.",
