            "h": "믿음을 말하고 받는 세례",
            "t": "1689년 9월 초, 런던에서 여러 침례교 교회의 목회자와 대표들이 며칠 동안 모였습니다. 이들은 하나님의 영광과 교회들의 유익을 위해 살펴볼 일을 의논하려 모였다고 적고, 앞서 낸 신앙고백(믿음을 조목조목 적어 고백한 글)을 교회 사람들에게 권했습니다. 이것이 1689년 런던 침례교 신앙고백입니다.¹\n\n이 글을 다시 내는 까닭은 자기들의 믿음을 오해하는 사람들에게 믿음을 알리는 것이었습니다. 앞서 낸 머리말은 웨스트민스터 신앙고백의 순서와 낱말을 따랐다고 밝히고, 새로운 말을 더하려는 뜻은 없다고 적습니다. 서명한 사람들은 세례에서 자기들과 생각이 다른 그리스도인들에게도 자기들의 믿음을 알리고 싶어 했습니다.²\n\n이 교회들이 지키려던 것은 두 가지입니다. 하나는 교회가 믿음을 고백한 사람들이 서로 약속하여 모인 곳이라는 것입니다. 고백서는 그리스도께서 사람들을 불러 한 교회로 모으신다고 말합니다. 다른 하나는 세례를 그 고백에 따라 받는다는 것입니다. 고백서는 뉘우침과 믿음과 순종을 참되게 고백하는 사람이 세례를 받는다고 합니다(29장 2절).³\n\n같은 말은 다른 교회들의 글에도 있습니다. 1611년 영국 사람들이 암스테르담에서 낸 신앙 선언도 교회를 믿음을 고백한 사람들의 모임으로 말하고 어린아이에게는 세례를 주지 않는다고 합니다.⁴ 오늘의 메노나이트 교회도 자기 신앙고백에 믿음을 고백한 사람이 받는 세례를 씁니다. 두 집의 글은 셋째 글에서 나란히 읽습니다.⁴",
