            "t": "이 글은 1689년 고백서가 예배의 부분으로 꼽는 것들을 한 주일 모임의 흐름으로 이어 그려 봅니다. 고백서는 그리스도께서 각 교회에 예배와 질서를 정할 권한을 주셨다고 하므로(26장 7절), 순서는 교회마다 다를 수 있습니다.⁵ 먼저 모인 사람들이 성경을 읽고 함께 기도합니다. 고백서는 여럿이 함께 드리는 기도를 모인 사람들이 아는 말로 하라고 합니다(22장 3절). 시편과 찬송과 신령한 노래를 함께 마음으로 부릅니다.\n\n다음에 말씀을 전하고 듣고, 서로 가르치고 권하는 시간을 가집니다. 고백서는 설교가 목사의 맡은 일이지만 목사에게만 한정되지 않고, 은사를 받아 교회가 부른 다른 사람도 전할 수 있다고 합니다(26장 11절). 이 모임을 섬기는 사람은 장로(교회를 돌보는 직분)와 집사입니다. 고백서는 이들을 교회 전체의 투표로 뽑고, 기도로 세워 일을 맡긴다고 합니다(26장 8~9절).⁵\n\n이 모임에는 세례를 받는 날이 있습니다. 믿음을 고백한 사람이 아버지와 아들과 성령의 이름으로 물에서 세례를 받습니다(29장 3절). 고백서는 세례를 예배의 한 부분으로 꼽습니다(22장 5절).⁵\n\n이 모임에서는 주의 만찬(빵과 잔을 나누는 일)을 하기도 합니다. 고백서는 주의 만찬을 예수께서 잡히시던 밤에 세우신 것이라고 하며, 그리스도의 죽으심을 기억하고 알리며 서로의 사귐을 확인하는 일이라고 하고(30장 1절), 목회자가 기도한 뒤 빵을 떼어 잔과 함께 나눈다고 합니다(3절).⁵"
