            "t": "이 글은 침례교와 메노나이트가 자기를 설명한 글을 따라 읽습니다. 1689년 고백서 29장은 세례의 뜻을 이렇게 말합니다. 세례는 그리스도께서 정하신 것으로, 받는 사람에게 그분의 죽음과 부활에 이어졌다는 표이고 죄 용서와 새 삶을 하나님께 드린다는 뜻이 있다고 합니다(1절). 방식은 아버지와 아들과 성령의 이름으로 물로 베풀며, 온몸을 물에 잠그는 것이 필요하다고 합니다(3~4절).⁶\n\n메노나이트 신앙고백은 1995년 7월 미국 위치타에서 두 메노나이트 교단의 대표들이 채택한 글입니다. 서문은 재세례파(믿음을 고백한 사람의 세례를 가르친 16세기 사람들)를 앞선 사람들로 소개하고, 1527년 슐라이트하임에서 쓴 일곱 조항을 말합니다. 그 첫 조항은 뉘우치고 삶을 바꾸었으며 죄 용서를 믿는 사람에게 세례를 준다고 합니다.⁷ 24개 조 가운데 11조는 죄를 고백하고 그리스도를 따르기로 한 사람이 스스로 청하면 세례를 준다고 하고, 세례를 죄를 씻음과 용서의 표이자 교회 앞에서 그리스도의 길을 걷겠다는 약속이라고 말합니다.⁶\n\n받는 사람에 대해서는 두 글이 같은 방향을 말하고, 둘 다 세례를 그리스도를 따르는 새 삶과 이어 말합니다. 방식에 대해서는 다르게 말합니다. 침례교 고백서는 잠그는 방식이 필요하다고 하고, 메노나이트 고백서의 해설은 교회가 잠그기와 붓기와 뿌리기를 쓸 수 있다고 합니다.⁶ 아래 표는 두 글이 교회와 주의 만찬을 말한 곳을 모은 참고입니다.\n\n| 물음 | 1689년 런던 침례교 신앙고백 | 메노나이트 신앙고백(1995) |\n| --- | --- | --- |\n| 교회는 | 26장 5~6절: 그리스도가 불러 모으신 사람들이 서로에게 자신을 맡기고 함께 걷는 지역 교회 | 9조: 지역 교회에 모인 믿는 이들의 공동체이며, 교회들과 세계 믿음의 공동체로 이어짐 |\n| 주의 만찬은 | 30장 1절: 그리스도의 죽으심을 기억하고 알리며, 믿음을 북돋우고 서로의 사귐을 확인함 | 12조: 새 언약을 감사로 기억하고 하나님과 서로에게 한 약속을 새롭게 하며 주의 죽으심을 알림 |"
