                "alt": "3권의 교회의 강을 오늘까지 이은 그림. 동쪽 교회와 가톨릭교회의 두 줄기가 이어 흐르고, 1517년 뒤 루터교, 개혁교회와 장로교, 침례교와 메노나이트, 성공회가 같은 굵기의 줄기로 갈라져 흐르며, 1739년 무렵 감리교와 성결교, 복음주의와 독립 교회가, 1906년 무렵 오순절과 은사 운동이 같은 굵기의 줄기로 이어진다. 강 위에 1517년, 1739년, 1906년, 1948년, 1999년 이름표가 있고 노란 칠이 7과가 다루는 줄기(감리교와 성결교 줄기)를 보여 준다. 줄기의 굵기와 순서에 뜻이 없다. 사람은 없다.",
