            "t": "성결교회는 이 본문을 사중복음과 이어 읽습니다. 성결과 재림이 한 구절에 나란히 있다는 점도 눈에 띕니다. 감리교 신조 10조는 선한 행위를 살아 있는 믿음의 열매로 말하고, 웨슬리의 일반 규칙은 이 열매가 이웃을 향한 선한 일로 나타나야 한다고 했습니다. 그래서 감리교는 서로 안부를 묻는 작은 모임을 곁에 두었습니다. 웨슬리는 찬송 모음도 경험하고 살아 내는 믿음의 가르침을 담은 작은 모음이라 불렀습니다.⁷\n\n우리와 같은 것. 웨스트민스터 신앙고백 11장 1절은 하나님이 믿는 이를 값없이 의롭다 하시며 그 믿음도 하나님의 선물이라고 말하고, 2절은 그 믿음이 홀로 있지 않고 사랑으로 일하는 믿음이라고 말합니다. 13장 1절은 새로 난 사람이 그리스도의 죽음과 부활의 은덕과 말씀과 성령으로 참되게 거룩해진다고 말합니다.⁷\n\n다른 것. 웨슬리는 마음을 가득 채우는 사랑을 믿음으로 기대하라고 했고, 죄가 없어졌다고 단정하는 일은 경계했습니다. 웨스트민스터 신앙고백 13장 2절은 거룩해지는 일이 이 세상에서는 완전하지 않고 싸움이 이어진다고 말합니다. 거룩함이 이 세상에서 어떻게 이루어지는지를 두 문서가 각각 이렇게 말합니다.⁷\n\n이 교회들에게서 우리는 믿음이 마음의 일이면서 삶의 일이라는 것과, 작은 모임에서 서로의 안부를 묻는 일의 선물을 배웁니다. 거룩함을 주님이 오시는 날의 소망과 함께 품는 성결교회의 눈, 노래로 믿음을 배워 온 감리교의 길도 선물입니다.",
