            "t": "1. 웨슬리 일지 1738년 5월 24일(수)(CCEL 웨슬리 일지): 새벽 다섯 시쯤 신약을 펴 베드로후서 1:4와 마가복음 12:34를 만난 일, 오후 성 바울 성당의 찬양(시편 130편), 저녁 올더스게이트 거리의 모임에서 루터의 로마서 머리글을 읽던 일, \"마음이 이상하게 뜨거워졌다\", 그리스도 한 분만 믿는다는 느낌과 죄가 없어졌다는 확신, 핍박한 사람들을 위한 기도, 곁의 사람들에게 말한 일, 이어진 의심과 밤의 유혹.\n2. 웨슬리 설교 43번 「성경이 말하는 구원의 길」(1872년 판 본문, 에베소서 2:8이 본문): 서론 2~3(믿음과 구원), I.3~4(구원의 두 부분과 새로 남), I.9(온전한 사랑), II.2(그리스도가 나를 사랑하시고 나를 위해 자신을 주셨다는 확신), III.3(믿음이 용서와 같이 거룩하게 되는 일의 조건), III.18(믿음으로 지금 기대하라는 청).\n3. 일반 규칙(웨슬리 형제, 1743년 5월 1일 서명, 6판 본문과 연합감리교회 교회법 2016년 판 본문): 1739년 말 런던에서 여덟이나 열 사람이 찾아온 일과 목요일 저녁 모임, 신도회, 한 반에 열두 사람쯤과 인도자의 매주 만남, 세 가지 규칙(해를 끼치지 않기, 선을 행하기, 은혜의 길에 참여하기).\n4. 연합감리교회 출판부(UMPH), 「예배의 기본 틀」과 「기본 틀로 드리는 주일 예배 순서」(umcdiscipleship.org): 들어섬, 말씀 선포와 응답, 감사와 성찬, 보냄의 네 부분과 세부 순서.\n5. 감리교 신조(25개 조): 연합감리교회 교회법(2020·2024년 판) 본문의 5조, 9조, 10조, 12조, 17조, 18조(한국어 문장은 영문을 풀어 쓴 것). 웨슬리가 영국 교회 39개조를 줄여 미국 감리교인을 위해 만들었고 1784년 모임이 받아들였다는 설명은 Schaff, Creeds of Christendom, 감리교 신조 소개에서 확인했다.\n6. 기독교대한성결교회 총회 누리집의 「사중복음」 페이지(네 이름과 데살로니가전서 5:23 인용)와 「총회소개」의 연혁(1907년 5월 서울 종로의 복음전도관). 이 카드는 교단이 자기를 소개하는 이름과 연혁만 옮겼다.\n7. 웨스트민스터 신앙고백 11장 1~2절, 13장 1~2절(CCEL 본문). 웨슬리 설교 43번 I.9, III.11. 감리교 신조 10조. 일반 규칙의 둘째 규칙(선을 행하기).\n8. 웨슬리, 「감리교 사람들이 쓰는 찬송 모음」 머리말(런던, 1779년 10월 20일, Wesley Center 게재본): 찬송이 공적 예배의 적지 않은 부분이라는 말과 이 책을 \"경험하고 실천하는 믿음의 작은 가르침 모음\"이라 부른 말(이 책의 번역)."
