    "guide": "성령 세례, 방언, 은사 같은 말은 어떤 분에게는 익숙하고 어떤 분에게는 낯설거나 조금 불편할 수 있어요. 그런 경험이 있는지 묻거나 증명하라고 하지 말고, 경험이 있는 분도 없는 분도 편하게 앉을 수 있게 해 주세요. 그럴 때는 \"교회마다 성령의 일을 다르게 설명해 왔다\"는 한 줄만 붙잡아 주세요. 오순절 교회의 예배와 가르침은 그 교회가 자기를 설명한 글로 먼저 읽는 시간이에요. 우리 교회와 다른 곳이 나오면 누가 맞는지 가리기보다 서로 무엇을 소중히 여기는지 듣는 쪽으로 이끌어 주세요. 병 고침이나 방언을 어떻게 이해하는지는 교역자와 나누면 좋아요. \"우리와 같은 것, 다른 것\" 문단에서 우리 교회의 입장을 더하는 일은 교역자 몫이에요. 모른다고 해도 괜찮아요.",
