            "t": "1906년 로스앤젤레스에 윌리엄 시모어라는 흑인 설교자가 있었습니다. 그는 텍사스에서 찰스 파함의 가르침을 받았습니다. 파함은 방언(성령이 주시는 대로 다른 말로 말하는 일)을 성령 세례(성령으로 가득 채워지는 경험)의 첫 표시로 가르친 사람입니다.¹\n\n시모어는 로스앤젤레스의 작은 교회에 설교자로 초대받았습니다. 그가 방언을 성령 세례의 표로 가르치자 그의 가르침이 그 교회에서 받아들여지지 않았고, 모임은 개인 집으로 옮겨졌고, 1906년 4월 아주사 거리 312번지의 옛 교회 건물에서 모이기 시작했습니다. 이 모임에는 흑인도 백인도 함께 있었습니다.¹\n\n그해 9월, 이 모임이 낸 신문 『사도적 신앙』의 첫 호는 건물을 아래층 한 칸이 널찍한 옛 감리교 예배당으로 소개합니다. 건물이 모자랄 만큼 사람이 모였고, 찾아온 이들은 하루에도 여러 번 제단 앞에 나와 기도했습니다. 의심을 품고 찾아온 설교자들 가운데 일부는 마음이 꺾여 용서를 구했다고 적혀 있습니다.²\n\n왜 이 모임이 생겼을까요. 이들은 사도행전 2장의 오순절이 다시 일어났다고 믿었습니다. 같은 첫 호 머리기사의 제목이 \"오순절이 왔다\"이고, 글은 이 일을 오순절과 성령 세례에 이어 말하고, 1901년 토피카에서 있었던 일도 이야기합니다.² 이 믿음의 뿌리에는 거룩해지기를 더 깊이 구하던 19세기 후반 감리교 신자들의 흐름이 있습니다. 그 가운데서 오순절 날 제자들에게 일어난 일을 오늘도 구하는 사람들이 나왔습니다.¹",
