            "h": "손을 들고 노래하는 모임",
            "t": "이 카드는 미국의 한 교단인 하나님의 성회가 2008년에 채택한 예배 문서가 그린 모임을 따라 읽습니다. 오순절 교회 전체를 대표하는 글은 아니고, 문서는 정해진 차례도 두지 않으니 아래 흐름은 모임마다 달라집니다.³ 사람들은 노래로 모임을 엽니다. 시와 찬송과 영의 노래(성령 안에서 부르는 노래)를 함께 부릅니다.³\n\n문서는 시편 63편 4절에서 시인이 손을 들고 하나님을 찬양하는 모습을 성경이 말하는 찬양의 한 모양으로 소개합니다. 노래 뒤에는 기도가 있습니다. 바울이 혼자 하는 기도에서 방언을 귀하게 여겼다고 문서는 말합니다. 성경 읽기는 예배의 중심이었고 설교와 가르침이 늘 함께했다고도 합니다.³\n\n여러 사람이 모임에 함께하는 것도 문서가 강조하는 모습입니다. 모두가 알아들을 수 있는 말로 하나님의 뜻을 전하는 예언이 가장 귀하게 여겨지고, 방언은 해석되어야 모두에게 유익이 됩니다. 이런 말은 차례를 지켜 하고 서로 살펴 확인하라는 바울의 안내를 따릅니다(고린도전서 14:27~31). 모든 것의 기준은 교회를 세우는 일입니다.³\n\n모임 끝에는 믿고 따르기로 마음을 정하라고 청하는 시간이 올 수 있습니다. 문서는 신약에 정해진 초청의 틀은 없지만 그런 부름은 많다고 말합니다.³ 모임에는 세례와 성찬도 있습니다. 하나님의 성회는 물세례를 물에 잠기는 방식으로 하며 그리스도와 함께 죽고 다시 사는 것을 보여 준다고 말합니다. 성찬은 빵과 포도로 하며 그리스도의 죽음을 기억하고 다시 오심을 기다립니다.⁴"
