            "t": "이 카드는 미국 하나님의 성회가 자기 믿음을 적은 열여섯 개 조의 기본 진리를 우리 말로 풀어 읽습니다. 앞의 조들은 구약과 신약을 믿음과 삶의 으뜸 권위로 두고, 한 분 하나님을 아버지와 아들과 성령으로 고백하며, 구원은 그리스도의 피로 오고 회개와 믿음으로 받는다고 말합니다. 5조는 안으로는 성령의 증언이, 밖으로는 의롭고 거룩한 삶이 그 표가 된다고 덧붙입니다.⁴\n\n이 과의 본문과 가장 가까운 것은 7조와 8조입니다. 7조는 믿는 사람이 구원받아 새로 난 일과 구별되고 그 뒤에 따라오는 성령 세례를 기대하고 구할 수 있다고 말합니다. 초대 교회에서처럼 모든 믿는 이가 간절히 구해야 한다고 합니다. 까닭은 이 세례가 삶과 섬김의 힘을 주고, 하나님을 높이는 마음과 더 깊은 헌신, 그리스도와 잃은 영혼을 향한 사랑을 깊게 하기 때문입니다. 8조는 그 첫 표시가 성령이 주시는 대로 다른 말로 말하는 것, 곧 방언이라고 말합니다. 이 방언은 교회 안에서 해석되는 방언과 본질은 같지만 쓰임이 다르다고 덧붙입니다.⁴\n\n9조는 거룩하게 되는 일을 악에서 떠나 하나님께 자신을 드리는 삶이라 하고, 그리스도와 하나 된 것을 날마다 믿고 성령께 맡기는 것으로 이룬다고 말합니다. 성경이 거룩함을 주님을 뵙는 일과 이어 말한 대목도 함께 듭니다. 10조는 교회를 그리스도의 몸이자 성령으로 하나님이 머무시는 곳이라고 말합니다.⁴\n\n아래 표는 기본 진리에서 몇 가지 질문의 답을 찾아보는 참고입니다.\n\n| 질문 | 답이 있는 곳 | 한 줄 |\n| --- | --- | --- |\n| 교회는 무엇을 위해 있나 | 10조 | 세상에 복음을 전하고, 예배하고, 그리스도를 닮아 가도록 돕는다 |\n| 병 고침은 | 12조 | 복음의 한 부분이며 믿는 이의 특권이다 |\n| 주님이 다시 오심은 | 13조 | 교회의 복된 소망이다 |"
