            "t": "사도행전 2장은 오순절 아침에 제자들이 한 집에 모여 있던 장면으로 시작합니다. 그때 하늘 쪽에서 큰 바람 같은 울림이 일어나 방 안이 그 소리로 찼습니다. 사람들 눈에는 불꽃처럼 생긴 것이 보였고, 그것이 한 사람 한 사람 위에 머물렀습니다. 그러자 모두에게 성령의 충만함이 임했고, 그들은 저마다 자기 것이 아닌 다른 말로 하나님을 말하기 시작했습니다. 이어지는 5~11절은 여러 나라에서 온 사람들이 자기 나라 말로 하나님의 큰일을 듣고 놀랐다고 전합니다.\n\n고린도전서 12장에서 바울은 먼저, 성령이 아니고서는 누구도 예수를 주님이라 부를 수 없다고 말합니다. 그러고는 은사(성령이 주시는 선물)도, 맡은 일도, 힘 있는 일도 여러 가지인데 그 뒤에는 한 성령, 한 주님, 한 하나님이 계신다고 합니다. 성령이 한 사람 한 사람에게 나타나시는 까닭은 함께 사는 모두에게 도움이 되게 하려는 것입니다.\n\n그 선물의 예로 바울은 지혜롭게 말하는 힘, 아는 것을 전하는 힘, 남다른 믿음, 병을 낫게 하는 힘, 기적을 일으키는 힘, 하나님의 뜻을 전하는 예언, 어느 영이 참인지 가려내는 힘, 여러 가지 방언, 그 방언을 풀어 주는 힘을 듭니다. 각자에게 무엇을 줄지는 한 분 성령이 정하십니다.",
