            "t": "두 본문은 성령이 하신 일을 다른 자리에서 보여 줍니다. 사도행전 2장은 성령이 오신 첫 장면이고, 고린도전서 12장은 성령이 주신 선물들이 한 교회 안에서 어떻게 쓰이는지를 말합니다. 하나님의 성회의 기본 진리 7조는 성령 세례가 이 선물들을 가져온다고 말합니다.⁴ 바울은 이어 선물이 여럿이어도 한 몸의 지체처럼 함께 쓰여야 한다고 말하고(12:12 이하), 고린도 교회의 모임에서는 방언을 풀어 주어 서로를 세우라고 안내합니다(14장).\n\n가톨릭교회 안에도 은사(성령이 주시는 선물)를 소중히 여기는 움직임이 있습니다. 제2차 바티칸 공의회의 『교회 헌장』 12항은 은사를 감사로 받되 그 참됨과 바른 쓰임은 교회를 이끄는 이들이 살피라고 말합니다. 2015년 교황은 이 움직임을 은총의 흐름이라 불렀습니다.⁵\n\n우리와 같은 것. 니케아-콘스탄티노플 신경은 성령을 주님이시며 생명을 주시고 예언자들을 통해 말씀하신 분이라고 고백합니다. 고린도전서 12장은 성령으로만 예수를 주님이라 고백할 수 있다고 하고(3절), 선물은 여럿이어도 성령은 한 분이라고 말합니다(4~6절).⁶\n\n다른 것. 하나님의 성회는 성령 세례를 새로 남과 구별되는 경험으로 말하고 방언을 그 첫 표시로 말합니다.⁴ 교회마다 성령의 일을 설명하는 방식은 같지 않습니다.\n\n오순절 교회에서 우리는 하나님을 노래로 기뻐하는 마음과, 선물이 모두의 유익을 위해 주어진다는 말씀의 무게를 선물로 받습니다.",
