    "guide": "복음주의, 독립 교회, 초교파라는 말이 낯설 수 있어요. 그럴 때는 \"복음주의는 한 교단의 이름이 아니라 여러 교회에 걸친 흐름의 이름이고, 독립 교회는 한 교단에 속하지 않고 그 교회가 스스로 일을 정하는 교회\"라는 두 줄만 붙잡아 주세요. 우리 교회와 다른 점이 나오면(예배의 모양을 교회가 정한다, 설교를 중심에 둔다 같은 것) 어느 쪽이 나은지 가리는 시간이 되지 않도록 해 주세요. 지금의 정치나 사회 쟁점과 이어서 복음주의를 말하는 이야기가 나오면 이 과가 다루지 않으니 교역자와 나누자고 안내해 주세요. 누가 \"구원받았는지\" 서로 묻거나 신앙을 점검하는 분위기로 흐르지 않게 해 주세요. 모르는 것이 나오면 모른다고 해도 되고, \"우리와 같은 것, 다른 것\" 문단에서 우리 교회의 입장을 더하는 일은 교역자 몫이에요.",
