            "h": "교단을 넘어 한 글 아래 모인 사람들",
            "t": "1974년 7월, 스위스 로잔에 여러 나라와 여러 교단의 그리스도인이 모였습니다. 복음을 널리 알리는 일을 함께 의논하려는 큰 모임이었습니다. 서로 다른 교단에서 온 사람들이 끝날 무렵 함께 서명할 글이 필요했고, 초안에는 수백 개의 고침 요청이 들어왔습니다. 글을 다듬는 위원회의 의장 존 스토트는 이틀 밤을 새워 최종 글을 썼고, 아흐레째 되던 날 많은 참가자가 이름을 적었습니다.¹\n\n이 글이 로잔 언약입니다. 언약은 서로 한 약속이라는 뜻입니다. 성경이 믿음과 삶의 유일한 기준이라고 말하고, 그리스도만이 구원자라고 말하며, 복음을 알리는 일을 교회의 으뜸 일로 꼽습니다. 그러면서 이웃과 사회를 섬길 책임도 같은 글의 5항에 두었습니다. 스토트가 이 항을 앞쪽으로 옮기고 표현을 힘주어 고쳤다고 합니다.²\n\n이 글은 한 교단의 글이 아닙니다. 복음주의(복음을 소중히 여기는 흐름)라는 이름도 한 교회의 이름이 아니라 여러 교회에 걸친 흐름의 이름입니다. 영국 역사가 데이비드 베빙턴은 1730년대부터 이 흐름을 따라가며 성공회와 스코틀랜드 교회, 그 밖의 교회들을 함께 다룹니다.³\n\n베빙턴이 정리한 네 가지로 흔히 소개되는 것이 있습니다. 성경을 각별히 여기고, 그리스도의 십자가를 중심에 두고, 삶이 바뀌어야 한다고 말하고, 믿음을 행동으로 드러내는 것입니다. 이것은 역사가가 붙인 이름표이고, 복음주의 교회가 모두 이 말로 자기를 소개하는 것은 아닙니다.³",
