            "h": "한 교회가 소개한 주일",
            "t": "이 카드는 웨일스의 한 복음주의 교회가 누리집에서 자기 주일 모임을 소개한 글 하나를 따라 읽습니다. 방문하려는 사람을 위한 짧은 안내글입니다. 다른 교회의 모임이 모두 이와 같다는 뜻은 아닙니다.\n\n이 교회는 주일 예배를 하나님께 예배드릴 기회라고 부르며, 오전 열한 시와 저녁 여섯 시에 모입니다. 옷차림에 정해진 규칙은 없고 방문하는 사람을 환영한다고 적습니다. 설교는 대개 목사가 맡습니다. 먼저 광고가 있고, 다음에 옛 찬송과 새 찬송을 부릅니다. 이어 성경을 읽고, 설교자가 기도한 뒤 읽은 본문을 풀어 줍니다. 모두 한 시간 남짓이고, 교회는 영어 새 킹 제임스 성경을 쓰며 방문한 사람에게도 성경을 건넨다고 합니다.⁴\n\n한 달에 두 번은 주의 만찬(빵과 포도주를 나누는 모임)이 더해져 십오 분쯤 길어집니다. 처음 온 사람은 앉아서 지켜보거나 빵과 잔을 그냥 건네도 된다고 안내합니다. 예배 뒤에는 목사나 교인과 편하게 이야기를 나눌 수 있고, 저녁 예배는 대개 옆 교실에서 간단한 다과를 나누며 끝납니다.⁴\n\n영국의 독립 복음주의 교회 모임의 신앙 기초는 지역 교회가 예배와 설교, 세례와 주의 만찬, 돌봄, 권징(잘못을 바로잡는 일), 전도에 함께 힘쓴다고 말합니다. 또 세례와 주의 만찬을 그리스도가 복음의 눈에 보이는 표로 주신 것이라고 말합니다.⁵ 웨일스 교회의 소개글은 이 모임과의 관계를 밝히지 않으며, 두 글은 서로 다른 곳에서 나온 글입니다."
