            "kind": "read",
            "h": "이 교회 가족이 자기를 말하는 글",
            "t": "이 카드는 두 글이 자기를 어떻게 말하는지 따라 읽습니다. 하나는 1974년의 로잔 언약이고, 다른 하나는 영국의 독립 복음주의 교회 모임이 내놓은 신앙 기초(열 가지 믿음의 항목)입니다.⁵ 두 글은 서로 다른 자리에서 나왔고, 겹치는 곳이 있습니다.\n\n로잔 언약은 서문에서, 하나님이 하시는 일에 마음이 움직이고 자기들의 실패에 마음이 아파 모였다고 밝힙니다. 그래서 허물도 적습니다. 복음을 알리는 일과 이웃을 섬기는 일을 떼어 놓은 적이 있다고 고백하고(5항), 교회들이 따로 애쓰며 같은 일을 겹쳐 하느라 증언이 흐려졌다고 고백합니다(7항). 그러고는 함께 기도하고 계획하고 일하겠다고 서로 약속하며 글을 맺습니다.⁶\n\n독립 교회 모임은 이 신앙 기초를 함께 나눕니다. 모임의 전국 책임자 존 스티븐스는 2022년 소개 글에서 독립을 각 교회가 스스로 다스리는 뜻으로 풀고, 예배의 모양도 교회가 정한다고 씁니다. 세례의 방식, 직분의 모양, 성령의 은사 같은 둘째 문제는 교회마다 달라도 된다고 합니다. 그는 이 자유가 가져올 위험도 꼽습니다. 고립, 점검받지 않음, 교리가 슬며시 변하는 일입니다.⁷ 신앙 기초 8항은 교회 사이의 사귐이 복음에 충실함 위에서 이루어진다고 말합니다.⁵\n\n두 글은 성경의 권위와 그리스도의 십자가를 앞에 두는 점에서 겹치지만 생김새는 다릅니다. 언약은 여러 나라 사람이 한 번 모여 서로 한 약속이고, 신앙 기초는 교회들의 모임이 함께 나누는 믿음의 목록입니다. 아래 표는 두 글이 같은 질문에 답한 곳을 나란히 놓은 참고입니다.\n\n| 질문 | 로잔 언약(1974) | 독립 복음주의 교회 모임의 신앙 기초 |\n| --- | --- | --- |\n| 성경은 어떤 책인가요? | 2항: 구약과 신약은 하나님이 영감하신 참된 말씀이고 믿음과 삶의 유일한 기준 | 2항: 구약과 신약만이 믿음과 삶의 최종 권위 |\n| 그리스도의 죽으심은 무엇인가요? | 3~4항: 그리스도는 유일한 구원자이고 죄를 위해 죽으시고 다시 살아나심 | 5항: 죄인을 대신해 죽으심 |\n| 복음을 들은 사람은 어떻게 되나요? | 4항: 응답한 사람은 그리스도를 따르고 교회에 속해 세상을 섬김 | 4항, 6항: 새로 태어나야 하고 하나님이 회개와 믿음을 주심 |\n| 교회는 무엇을 하나요? | 6항: 아버지가 그리스도를 보내신 것처럼 교회도 세상으로 보냄 받음 | 8항: 예배, 설교, 세례와 주의 만찬, 돌봄, 전도 |"
