            "kind": "read",
            "h": "본문 설명 · 듣고 믿고 전하는 줄",
            "t": "이 책은 이 본문을 로잔 언약과 이어 읽어 봅니다. 언약 6항은 아버지가 그리스도를 보내신 것처럼 그리스도께서 교회도 세상으로 보내신다고 말합니다. 4항은 복음을 알리는 일을, 그리스도가 죄를 위해 죽으시고 다시 살아나셨다는 소식을 전하는 일로 풀어 줍니다. 바울의 사슬에서 \"전하는 사람\"과 \"보내심\"이 놓인 자리와 닿아 있습니다. 이 이음은 이 책이 놓아 본 것입니다.⁸\n\n그리스도를 가리키는 자리는 9절과 13절의 \"주님\"입니다. 전해지는 소식도, 부르는 대상도 그분입니다. 9절의 고백은 그 소식을 한 줄로 줄인 말로 읽힙니다. 요한복음 20:21에서 부활하신 그분이 아버지가 자신을 보내신 것처럼 제자들을 보낸다고 하신 말씀과 같은 방향입니다.\n\n우리와 같은 것, 다른 것. 니케아-콘스탄티노플 신경은 교회를 하나이고 거룩하고 보편적이며 사도에게서 온 교회라고 고백합니다. 웨스트민스터 신앙고백 14장 1절은 믿음이 보통 말씀을 전하는 일로 일어난다고 합니다. 다른 것은 예배의 모양입니다. 가톨릭, 정교회, 성공회는 정해진 예배서를 따르고, 영국의 독립 복음주의 교회 모임은 예배의 모양을 각 교회가 정한다고 설명합니다.⁸\n\n이 교회에서 배울 점. 우리가 받은 선물은, 한 사람에게 소식이 닿기까지 이어진 여러 사람의 걸음을 기억하게 하는 것입니다. 또 교단의 울타리를 넘어 모인 사람들이 서로의 허물을 함께 고백한 모습입니다. 언약 5항과 7항의 고백에서 읽은 것입니다.",
