    "guide": "세계 교회라는 말이 크게 느껴질 수 있어요. 그럴 때는 \"교회는 여러 나라와 여러 말 속에서 자기 말로 믿음을 이어 왔다\"는 한 줄만 붙잡아 주세요. 이 과는 한 나라나 한 교회를 대표처럼 말하지 않으니, 모임에서도 \"아프리카 교회는 이렇다\"처럼 한꺼번에 말하는 것을 가볍게 바로잡아 주세요. 어느 대륙의 교회가 더 크다거나 더 뜨겁다는 비교가 나오면 이 과가 쓰지 않는 말이라고 안내하고, 선교사와 현지 교회 사이의 아픈 이야기(식민 시대의 일 같은 것)가 나오면 모두의 이야기로 짧게 듣고 넘어가 주세요. 모르는 것이 나오면 모른다고 해도 되고, \"우리와 같은 것, 다른 것\" 문단에서 우리 교회의 입장을 더하는 일은 교역자 몫이에요.",
