            "t": "스코틀랜드 출신 학자 앤드루 월스는 믿음의 중심이 한곳에 머물지 않고 이곳에서 저곳으로 옮겨 간다고 썼습니다. 예루살렘, 시리아, 이집트, 북아프리카에도 한때 믿음의 중심이 있었다고 그는 짚습니다. 어느 한 교회나 한 문화가 믿음을 혼자 가진 적은 없다는 것입니다. 그는 20세기에 중심이 남쪽으로 옮겨, 아프리카와 아시아와 남미의 교회가 앞으로 교회의 일을 빚어 가리라고 내다봅니다.¹\n\n월스는 이런 옮김이 가능한 까닭을 번역에서 찾습니다. 그리스도를 새로운 말과 문화로 옮길 때마다 그분의 새로운 면이 드러나고, 번역은 전해 받은 믿음을 풍성하게 했을 뿐 없애지 않았다고 합니다. 그의 글은 성막(하나님을 예배하던 이동식 천막)이 아프리카의 금으로 꾸며지고 아시아의 천으로 휘장이 드리워졌다는 그림으로 끝납니다.¹\n\n그런 길을 걸은 한 사람이 새뮤얼 아자이 크라우더입니다. 요루바 땅(오늘의 나이지리아)에서 태어난 그는 어린 나이에 노예 상인의 배에서 풀려나 시에라리온에 닿았고, 그곳에서 배웠습니다. 영국 성공회의 교회선교회 일꾼이 되어 요루바어로 성경과 기도서를 옮기는 일에 함께했고, 1864년 캔터베리 대성당에서 니제르 지방을 맡는 주교로 세워졌습니다.²\n\n2010년 케이프타운 로잔 대회의 서약은 모든 문화와 언어로 성경을 옮기고 퍼뜨리고 가르치는 일을 다시 다짐합니다. 같은 글은 하나님의 백성이 모든 나라에서 나와 서로 사랑하는 한 몸이라고 말합니다. 이 교회 가족이 지키려는 것은 자기 말로 성경을 읽고 기도하면서도, 멀리 있는 교회와 한 몸으로 이어지는 일입니다.³",
