            "h": "한 방에 둘러앉은 사람들",
            "t": "9과에서 본 1974년 로잔 대회장에는 서양 밖에서 온 사람도 적지 않았습니다.⁴ 그 가운데 라틴아메리카에서 온 르네 파디야는 「복음 전도와 세상」이라는 글을 스페인어로 발표했습니다. 그는 복음이 한 사람의 마음뿐 아니라 세상 전체에 닿는 소식이라고 했고, 어느 한 문화의 옷을 입은 신앙을 복음 자체로 여기지 말자고 했습니다. 청중은 큰 박수로 답했다고 합니다.⁴\n\n이어서 케냐 장로교회의 지도자 존 가투가 외국 선교사를 보내는 일을 한동안 멈추자는 의견을 냈습니다.⁴ 이런 목소리는 로잔 언약에 담겼고, 가투가 청한 \"멈춤\"은 글에서 \"줄임\"으로 부드러워졌습니다.⁴\n\n언약 8항은 서양 선교가 앞장서던 때가 지나고, 하나님이 어린 교회들을 큰 힘으로 일으키고 계신다고 말합니다. 모든 교회가 자기 지역에 복음을 알릴 길과 먼 땅에 사람을 보낼 길을 계속 살피라고도 권합니다. 9항은 복음이 이미 전해진 나라에서는 외국 선교사와 선교비를 줄이는 일이 교회가 스스로 서는 데 도움이 될 때도 있다고 말합니다. 선교사가 모든 대륙에서 모든 대륙으로 자유롭게 오가야 한다고도 말합니다.⁴\n\n10항은 복음이 그리스도께 뿌리내리면서도 그 땅의 문화와 이어진 교회를 낳아야 한다고 말합니다. 선교가 때로 복음과 함께 자기 나라의 문화까지 실어 보낸 일은 스스로 바로잡으려 합니다. 여러 말과 사정을 가진 교회들의 목소리가 한 글의 항마다 담긴 것이며, 서로 다른 곳에서 온 경험이 한 글로 모인 흔적입니다.⁴"
