            "h": "세 대륙의 교회가 자기를 말하는 글",
            "t": "이 카드는 세 대륙의 교회가 자기를 설명한 글을 하나씩 따라 읽습니다. 모두 한 대륙 교회 전체를 대표하는 글이 아니라, 그 자리에 모인 사람들이 자기 이름으로 쓴 글입니다.\n\n1974년 4월 타이완 타이베이에 아시아 여러 나라의 가톨릭 주교(교구를 맡아 돌보는 지도자)들이 모여 아시아 주교회의 연합회의 첫 총회를 열었습니다. 이들은 복음을 전하는 일의 첫째 과제를 그 땅에 선 교회를 세우는 일로 꼽았습니다. 그 교회는 하나님의 몸인 교회가 한 민족과 한 땅과 한 시대에 모습을 얻은 것이며, 사람들의 말과 예술과 바람을 함께 나누고 문화와 종교와 가난한 이웃과 겸손하게 대화한다고 설명합니다.⁵\n\n2007년 브라질 아파레시다에서 라틴아메리카와 카리브의 가톨릭 주교들이 낸 문서의 서론은, 복음이 이 땅에 온 것이 여러 민족과 문화가 극적이고 고르지 못하게 만난 한가운데였다고 적습니다. 또 사랑이신 하나님에 대한 믿음과 가톨릭 전통이 이 땅 사람들의 삶과 문화 안에 있는 귀한 재산이라고 말합니다.⁶\n\n2010년 남아프리카 케이프타운에서 열린 로잔 대회의 서약은 모든 문화와 언어로 성경을 옮기고 퍼뜨리고 가르치는 일을 다시 다짐합니다. 글은 2011년에 펴냈습니다. 글을 읽지 않는 문화에서도 성경이 전해지도록 하겠다고 덧붙입니다. 같은 글은 하나님의 백성이 모든 나라에서 나와 서로 사랑하는 한 몸이라고도 말합니다.⁷ 아래 표는 세 글이 답한 질문을 나란히 놓은 참고입니다.\n\n| 문서 | 모인 때와 곳 | 이 글이 답하는 물음 |\n| --- | --- | --- |\n| 아시아 주교회의 연합회 첫 총회 글 | 1974년, 타이베이 | 교회는 이 땅에서 어떤 모습으로 서야 하나요? |\n| 아파레시다 문서(서론) | 2007년, 아파레시다 | 복음은 이 땅에 어떤 모습으로 왔고 무엇이 귀한 재산으로 남았나요? |\n| 케이프타운 서약 | 2010년, 케이프타운 | 성경은 어느 말로 읽히고 가르쳐져야 하나요? |"
