            "t": "1. 월스(Andrew Walls)의 글 「세계 역사에서 본 오늘 교회의 선교」(Word & World, 2000년 겨울호, 17~21쪽): 신앙의 중심이 옮겨 다니고 어느 교회나 문화도 혼자 갖지 않는다는 설명, 예루살렘, 시리아, 이집트, 소아시아, 북아프리카의 옛 중심, 20세기에 중심이 남쪽으로 옮겼다는 판단, 번역이 전통을 풍성하게 했다는 말, 성막을 아프리카의 금과 아시아의 천으로 꾸민다는 끝그림.\n2. 크라우더: 『아프리카 그리스도교 인물 사전』(DACB)의 크라우더 항(교회선교회 등록부를 인용한 짧은 소개: 요루바 땅 출신, 시에라리온에서의 배움, 요루바어 번역 협력, 1864년 6월 29일 캔터베리 대성당에서 니제르 지방 선교 주교로 서임). 출생 지역과 노예선에서 풀려나 시에라리온에 닿은 일, 요루바어 성경 번역의 때: 뷔르템베르크 주립도서관 선교 성경 연표의 크라우더 쪽.\n3. 케이프타운 서약(2010, 제3차 로잔 대회) 1부 6항 B(모든 문화와 언어로 성경을 옮기고 퍼뜨리고 가르침), 1부 9항(하나님의 백성이 모든 나라에서 나와 서로 사랑함).\n4. 로잔 대회(1974)의 소집, 파디야와 가투의 발표, 가투의 \"멈춤\"이 글에서 \"줄임\"이 된 일, 아흐레째 서명: Stanley 2013. 8항, 9항, 10항: 로잔 언약(공개 본문).\n5. 아시아 주교회의 연합회 첫 총회(1974년 4월 22~27일, 타이베이) 글 「오늘의 아시아에서의 복음 전함」 9~12항(그 땅에 선 교회, 그 교회가 사람들의 말과 예술과 바람을 나눔, 문화와 종교와 가난한 이웃과의 대화): 아시아 주교회의 연합회가 공개한 모음집(『아시아 사목 지침 오십 년』)의 본문.\n6. 라틴아메리카와 카리브 주교회의(CELAM) 제5차 총회 문서(브라질 아파레시다, 2007년 5월 13~31일) 서론 4항(첫 문장: 복음이 극적이고 고르지 못한 민족과 문화의 만남 가운데 왔다)과 7항(첫 문장: 사랑이신 하나님에 대한 믿음과 가톨릭 전통이 이 땅 사람들의 삶과 문화 안의 귀한 재산): CELAM이 공개한 스페인어 본문.\n7. 케이프타운 서약 1부 6항 B(모든 문화와 언어, 글을 읽지 않는 문화까지), 1부 9항(하나님의 백성이 모든 나라에서 나와 서로 사랑함). 아프리카에서 번역과 신앙의 자리를 더 읽으려면 John S. Mbiti, Bible and Theology in African Christianity(Nairobi: Oxford University Press, 1986)와 Lamin Sanneh, Disciples of All Nations: Pillars of World Christianity(Oxford University Press, 2008)가 있다.\n8. 웨스트민스터 신앙고백 25장 2절, 니케아-콘스탄티노플 신경의 교회 대목(교황청이 공개한 『가톨릭교회 교리서』에 실린 신경 본문). 아시아 주교회의 연합회 글 9~12항(각주 5), 케이프타운 서약 1부 6항 B(각주 7)."
