          {
            "id": "cd11-r2",
            "kind": "read",
            "h": "서로의 예배에 손님으로 간 자리",
            "t": "이 카드는 암스테르담 총회의 공식 보고서를 따라 읽습니다. 1948년 8월 22일 일요일 오후 3시, 암스테르담의 니우어 케르크에 여러 나라의 교회 대표들이 모였습니다. 세계교회협의회를 세우는 첫 총회의 첫 예배였고, 여러 나라와 교회에서 온 사람들이 같은 순서를 함께 따라갔습니다. 행렬이 들어오고, 하나님을 부르며 잘못을 고백하는 기도가 있었고, 성경을 읽은 뒤 D. T. 니레스가 설교했습니다.⁴\n\n총회 기간의 아침 예배는 말하기보다 성경 읽기와 기도가 중심이었고, 인도하는 사람은 여러 전통에서 나왔습니다. 저녁에는 대표들이 회의하던 곳 어디서나 짧은 기도를 드렸는데, 총회 안내서에 실린 순서는 성공회의 저녁 기도를 바탕으로 한 것이었습니다.⁴\n\n가장 조심스러운 시간은 성찬(빵과 포도주를 나누며 그리스도를 기억하는 예배)이었습니다. 여러 전통의 교회가 함께 모인 자리여서 총회는 자기 이름으로 성찬을 드리지 않았습니다. 대신 네 전통이 각자 예배를 열었고, 참석자는 자기가 받을 수 있는 예배에서는 성찬에 참여하고 다른 전통의 예배에는 기도로 함께하도록 했습니다. 루터교의 예배에서는 다른 교회 사람도 많이 성찬을 받았습니다.⁴ 총회는 이 예배들로 일치와 다양함, 그리고 죄의 고백을 보이려 했습니다.\n\n비슷한 마음이 가톨릭교회의 일치 교령 8항에도 보입니다. 특별한 때에 일치를 위한 기도 모임에서 다른 교회 사람과 함께 기도하는 것은 허락되고 바람직하다고 하면서, 예배를 함께 드리는 일은 아무 때나 쓸 방법이 아니라고 말합니다.⁵\n\n| 총회에서 열린 성찬 예배 | 성찬을 받을 수 있다고 한 사람 |\n| --- | --- |\n| 네덜란드 개혁교회의 예배 | 자기 교회에서 세례받은 성찬 교인은 누구나 초대 |\n| 성공회의 예배 | 성공회 교인과, 성공회와 서로 성찬을 나누는 교회의 교인 (다른 사람의 참석도 환영) |\n| 정교회의 신성한 예배 | 정교회 교인 (다른 교회 사람은 기도로 함께하도록 초대) |\n| 루터교의 예배 | 세례받은 성찬 교인 누구나 |"
          },
          {
            "id": "cd11-r3",
            "kind": "read",
            "h": "일치를 말하는 세 글",
            "t": "그 뒤 여러 교회가 각자 자기 말로 일치를 말했습니다. 먼저 가톨릭교회입니다. 1964년 11월 21일 제2차 바티칸 공의회(가톨릭 주교들의 큰 회의)는 일치를 다룬 글, 곧 일치 교령을 반포했습니다. 첫머리는 그리스도인 모두의 일치를 되찾는 일이 공의회의 으뜸 관심 가운데 하나라고 말합니다. 까닭으로는 나뉨이 그리스도의 뜻에 어긋나고 세상을 걸려 넘어지게 한다는 점을 듭니다.⁵\n\n교령은 서로를 향한 마음도 적었습니다. 갈라질 때 양쪽에 잘못이 있었다고 인정하고, 지금 그 공동체에서 태어난 사람에게는 갈라짐의 죄를 물을 수 없다고 밝힙니다. 그리고 나뉨에 대해 하나님과 갈라진 형제들에게 용서를 구한다고 말합니다. 참으로 세례를 받고 그리스도를 믿는 사람은 불완전하게나마 가톨릭교회와 교제 안에 있다고도 합니다.⁵\n\n그러면 일치는 어떻게 이루어질까요? 교령은 마음의 돌이킴과 거룩한 삶, 일치를 위한 기도를 일치 운동의 바탕으로 꼽습니다. 서로 다른 교회의 전문가들이 마주 앉아 각자 자기 교회의 가르침을 깊이 설명하는 대화도 일치 운동의 한 모습으로 꼽습니다. 세례가 세례받은 모든 사람을 하나로 잇는 끈이 된다는 말도 있습니다.⁵\n\n그 뒤에도 일치를 말하는 글이 이어졌습니다. 1974년의 로잔 언약은 교회의 눈에 보이는 하나 됨을 진리 안에서 구했습니다(9과).⁶ 1999년에는 가톨릭교회와 루터교세계연맹이 칭의(하나님이 믿는 사람을 의롭다고 받아 주시는 일)에 관한 공동 선언에 서명했습니다. 이 선언은 12과에서 자세히 읽습니다.⁷\n\n| 글 | 낸 곳과 해 | 일치를 그리는 모양 |\n| --- | --- | --- |\n| 일치 교령 (8항, 22항) | 제2차 바티칸 공의회, 1964 | 기도가 일치 운동의 바탕이고, 세례가 세례받은 모든 사람을 잇는 끈이 된다고 봄 |\n| 로잔 언약 (7항) | 로잔 대회 참석자들, 1974 | 조직의 하나 됨은 여러 모양일 수 있다고 봄. 지역과 일에 따른 협력을 권함 |\n| 공동 선언 (40항, 43항) | 가톨릭교회와 루터교세계연맹, 1999 | 큰 줄기의 합의를 말하고, 그 합의가 두 교회의 삶과 가르침에 스며들어야 한다고 함 |"
          }
