            "id": "cd11-r4a",
            "kind": "read",
            "h": "본문의 자리",
            "t": "고린도전서 12장은 바울이 은사(성령이 사람마다 다르게 주시는 선물)를 두고 쓴 대목입니다. 고린도 교회의 모임에서 은사가 어떻게 쓰여야 하는지 이야기하다가, 바울은 은사가 다르다고 서로 높고 낮음을 가르던 교회에 몸의 그림을 들려줍니다.\n\n12~13절은 몸은 하나이지만 부분은 여럿이라고 하며, 출신과 처지가 달랐던 사람들이 같은 성령 안에서 세례로 한 몸에 들어왔고 모두 한 성령을 함께 받았다고 말합니다. 14~20절은 발이 자기는 손이 아니라고, 귀가 자기는 눈이 아니라고 해도 몸에서 빠지는 것은 아니며, 하나님이 뜻하신 대로 부분들을 두셨다고 합니다.\n\n21~27절은 어느 부분도 다른 부분에게 필요 없다고 할 수 없고, 약해 보이는 부분이 오히려 꼭 필요하다고 말합니다. 덜 귀해 보이는 부분은 더 정성스레 감싸고, 한 부분이 아프면 모두 아프고, 한 부분이 인정받으면 모두 함께 기뻐한다고 합니다. 마지막으로 바울은 너희가 그리스도의 몸이라고 맺습니다.",
