            "kind": "read",
            "h": "함께 고백한 은혜, 남은 말의 차이",
            "t": "1999년 10월 31일, 독일 아우크스부르크에서 가톨릭교회와 루터교세계연맹이 칭의에 관한 공동 선언에 서명했습니다. 칭의는 하나님이 믿는 사람을 의롭다고 받아 주시는 일을 가리키는 말이고, 16세기에는 서로 잘못이라고 선언하는 글이 오간 한복판의 물음이었습니다. 아우크스부르크는 1530년에 루터교의 신앙고백이 나온 도시이기도 합니다. 선언이 나오기 전까지 그 정죄는 두 교회를 가르는 힘으로 남아 있었다고 서문은 적습니다(1항).¹\n\n선언은 두 교회가 함께 고백합니다. 우리는 은혜로, 그리스도의 구원 사역을 믿는 믿음 안에서, 우리의 공로 때문이 아니라 하나님께 받아들여지고 성령을 받는다고 합니다(15항). 말과 신학적 설명과 강조의 차이는 남아 있지만 받아들일 수 있다고 적고(40항), 두 교회가 자기 과거를 가볍게 여기지도 부인하지도 않는다고 서문에서 밝힙니다(7항). 이 합의가 두 교회의 삶과 가르침에 스며들어야 한다는 말도 덧붙입니다(43항).¹\n\n아래 표는 일곱 교회가 같은 두 질문에 자기 문서로 답한 말을 옮긴 것입니다. 한 질문은 성경과 전통(교회가 대대로 전해 온 가르침)의 관계이고, 다른 한 질문은 사람이 하나님 앞에서 어떻게 받아들여지는가입니다. 이 가운데 성경과 전통은 선언이 다루지 않은 물음입니다. 세 표는 모두 가나다 순이며 순서와 칸의 크기에는 뜻이 없습니다. 칸은 각 교회 문서가 말한 것을 옮긴 것이고 괄호는 문서의 번호입니다.²\n\n| 교회 | 성경과 전통 | 구원의 길 |\n| --- | --- | --- |\n| 가톨릭교회 | 성경과 전통은 같은 하나님의 말씀에서 나와 서로 가까이 묶여 있으며, 교회는 계시된 모든 진리의 확신을 성경에서만 얻지 않는다(교리서 80~82항) | 칭의는 죄를 용서하고 안을 새롭게 하는 일이며, 은혜와 사람의 자유가 함께 이루어진다(교리서 1989항, 1993항) |\n| 감리교 | 구원에 필요한 것이 성경에 담겨 있어, 성경에 없는 것을 신앙 조항으로 요구할 수 없다(신조 5조) | 그리스도의 공로 때문에 믿음으로 의롭다 여겨진다(9조). 웨슬리는 칭의를 용서로, 함께 시작되는 마음의 새로워짐(성화)을 따로 말한다(설교 43) |\n| 개혁교회와 장로교 | 성경이 모든 신앙 다툼을 가리는 최종 판단자이며 교회 회의와 옛 교사들의 글도 성경으로 살핀다(웨스트민스터 신앙고백 1장 10절) | 그리스도의 순종이 우리 것으로 인정되고 믿음이 그것을 받는 유일한 도구이며, 그 믿음은 사랑으로 일한다(11장 1~2절) |\n| 루터교 | 예언자와 사도의 글인 성경만이 모든 가르침을 가리는 기준이고, 신경과 고백서는 그 이해를 증언한다(협화 신조 요약 1~2항, 8항) | 사람은 행위가 아니라 그리스도 때문에 믿음으로 값없이 의롭게 된다(아우크스부르크 신앙고백 4조) |\n| 성공회 | 성경에 구원에 필요한 모든 것이 담겨 있고, 교회는 예식을 정할 권한이 있으나 성경에 어긋나게 정할 수 없다(39개조 6조, 20조) | 그리스도의 공로 때문에 믿음으로 의롭다 여겨지며 우리 행위 때문이 아니다(11조) |\n| 정교회 | 성경은 하나님이 가르치신 글로서 교회가 이어 온 해석대로 읽으며, 교회의 증언도 성경에 못지않은 권위를 가진다(예루살렘 1672, 결의 2) | 믿음만이 아니라 사랑으로 일하는 믿음, 곧 믿음과 행위로 의롭게 된다(결의 13) |\n| 침례교 | 성경이 구원의 지식과 믿음과 순종의 유일하고 충분하며 확실한 기준이고 신앙 다툼의 최종 판단자이다(1689 고백 1장 1절, 10절) | 그리스도의 순종이 우리 것으로 인정되고 믿음이 유일한 도구이며, 그 믿음은 홀로 있지 않다(11장 1~2절) |",
            "imgs": [
              {
                "src": "cd00-family-12.jpg",
                "w": 1672,
                "h": 941,
                "alt": "3권의 교회의 강을 오늘까지 이은 그림. 동쪽 교회와 가톨릭교회의 두 줄기가 이어 흐르고, 1517년 뒤 루터교, 개혁교회와 장로교, 침례교와 메노나이트, 성공회가 같은 굵기의 줄기로 갈라져 흐르며, 1739년 무렵 감리교와 성결교, 복음주의와 독립 교회가, 1906년 무렵 오순절과 은사 운동이 같은 굵기의 줄기로 이어진다. 강 위에 1517년, 1739년, 1906년, 1948년, 1999년 이름표가 있고 노란 칠이 12과가 다루는 줄기(모든 줄기)를 보여 준다. 줄기의 굵기와 순서에 뜻이 없다. 사람은 없다.",
                "cap": "교회 가족 그림(노란 칠: 12과의 줄기)",
                "after": 1
              }
            ]
